def read_price(text):
    try:
        return int(text)
    except ValueError:
        print("'" + text + "' is not a number. Skipping.")
        return None

try:
    with open("prices.txt") as f:
        for line in f:
            if "," not in line:
                continue          # skip blank or broken lines
            item, raw = line.strip().split(",", 1)
            price = read_price(raw)
            if price is not None:
                print(item, "->", price)
except FileNotFoundError:
    print("No prices.txt yet. Save some prices first!")
finally:
    print("Done checking.")

def average(prices):
    if len(prices) == 0:          # bug fix 1: empty list crashed (ZeroDivisionError)
        return 0
    return sum(prices) / len(prices)

def test_average():
    assert average([1000, 2000]) == 1500
    assert average([]) == 0
    print("All tests passed!")

